corporate_design.toad_component_blueprint:
canvas {
  size: 920px 580px;
  fill: #FAF8F5;
  font-family: "Plus Jakarta Sans, sans-serif";
}

>warmCanvas = #FAF8F5;
>royalPurple = #7C3AED;
>cultureRose = #EC4899;
>darkIndigo = #1E1B4B;

rect #empCard {
  at: center of canvas;
  size: 820px 460px;
  fill: #FFFFFF;
  stroke: #E2E8F0;
  stroke-width: 1px;
  radius: 16px;
}

text #empHeader {
  at: top left of #empCard offset 36px 36px;
  content: "TEAM SPOTLIGHT // ONBOARDING CELEBRATION";
  font-size: 13px;
  font-weight: 700;
  color: >royalPurple;
}

text #empTitle {
  at: below #empHeader offset 12px;
  content: "Willkommen im Team, Sarah!";
  font-size: 32px;
  font-weight: 800;
  color: >darkIndigo;
}

rect #cultureBadge {
  at: below #empTitle offset 20px;
  size: 200px 32px;
  fill: alpha(>cultureRose, 0.15);
  radius: 9999px;
}

text #cultureText {
  at: center of #cultureBadge;
  content: "★ SENIOR PRODUCT DESIGNER";
  font-size: 11px;
  font-weight: 700;
  color: >cultureRose;
}
